#!/bin/sh
# SPDX-License-Identifier: GPL-3.0-only
# FM-ARCAVE's tests, none of which needs an FM-1. From the repo root:
#   sh tests/run_arcave_tests.sh
# 1. the game on the host: every script in tests/scripts plays through (title to the cave, the mending, each machine)
# 2. the browser build in Node (when build/emu exists): it loads with no imports, draws, sounds, follows a Link beacon
# 3. the update path (when build/fm-arcave.fwsc exists): Dinghy's own tests of the M-UPGRADE entry and the loader
# (tests/run_tests.sh is Dinghy's suite for its sample app and the SMK-37; FM-ARCAVE builds for the FM-1 only.)
set -e
cd "$(dirname "$0")/.."
OUT=build/host
mkdir -p "$OUT"
fail=0
run() { echo "== $1"; shift; "$@" || { echo "   FAILED"; fail=1; }; }
play() { tests/run_arcave.sh "$@" > "$OUT/$1.log" 2>&1 && grep -q '^sound' "$OUT/$1.log"; }

run "the intro: title, wake, roll, pads, the last stretch" play intro
run "the roll's music: the piece follows Rock along the course to the cave's own chord, the whole melody once he rolls well, a key playing the chord's notes (a step higher over G)" sh -c 'tests/run_arcave.sh rollmusic > build/host/rollmusic.log 2>&1 && grep -q "roll music: place 28, flow" build/host/rollmusic.log && grep -q "roll music: place 6, flow [0-9]*, melody 2" build/host/rollmusic.log && grep -q "roll key 12 plays 62 (place 0)" build/host/rollmusic.log && grep -q "roll key 12 plays 64 (place 23)" build/host/rollmusic.log && grep -q "roll music: place 29, flow" build/host/rollmusic.log'
run "the roll's music, standing still: the first chord only, no melody; the keys from C3 up to C6" sh -c 'tests/run_arcave.sh rollstill > build/host/rollstill.log 2>&1 && grep -q "roll music: place 28, flow 0, melody 0" build/host/rollstill.log && grep -q "roll key 0 plays 48 (place 28)" build/host/rollstill.log && grep -q "roll key 26 plays 84 (place 28)" build/host/rollstill.log && ! grep -q "roll music: place 0," build/host/rollstill.log'
run "power on: OCT- and OCT+ breathe three times from \"change language\", the words and PLAY on time beside them, then OCT dark" sh -c 'tests/run_arcave.sh octpulse > build/host/octpulse.log 2>&1 && grep -q "  3000 ms  lights: breathing 0000, PLAY 0" build/host/octpulse.log && grep -q "  4000 ms  lights: breathing 0003, PLAY 0" build/host/octpulse.log && grep -q "  9500 ms  lights: breathing 0003, PLAY 2" build/host/octpulse.log && grep -q " 10600 ms  lights: breathing 0000, PLAY 2" build/host/octpulse.log'
run "a language chosen over the title: no OCT breaths after it, PLAY as before" sh -c 'tests/run_arcave.sh octpulse2 > build/host/octpulse2.log 2>&1 && grep -q " 7000 ms  lights: breathing 0000, PLAY 0" build/host/octpulse2.log && grep -q " 8600 ms  lights: breathing 0000, PLAY 2" build/host/octpulse2.log'
run "the course, standing still: at a minute and a half \"keep going\" at the right edge, gone after five seconds" play keepgoing
run "the title in each language" play lang
run "the controls box by the start, HOME: the controls lesson, each step shown then done by the player (roll, hop, big hop, the jump onto the bounce mushroom; the other grip only shown), ALL DONE" play controls
run "the controls lesson, helped along: the wrong control brings a tip and flashes the right one (and so does waiting); doing a step during its demo takes it over" play controlstip
run "the PLAY button drawn as the green button in the wake line" play playbtn
run "Turkish: the title, the tip fading as the wake text comes in, the controls sheet" play turkish
run "the hollow behind the start: hidden by a rock face until Rock is on the ledge and rolls in: the third secret" sh -c 'tests/run_arcave.sh hollow 0 8 > build/host/hollow.log 2>&1 && grep -q "cave secret 3 found" build/host/hollow.log'
run "the settings, line by line" play menu
run "Dutch: the title, the wake text, the controls sheet, the settings, ABOUT" play dutch
run "Dutch: into the cave, the Hat, the rings, the dish, the jukebox" play dutchstory 1
run "into the cave, the Hat, the jukebox, the settings" play story 1
run "the jukebox past the Hat: its name at the screen's edge, Rock settling in its dip, PLAY: the rings" sh -c 'tests/run_arcave.sh juke 2 > build/host/juke.log 2>&1 && grep -q "^sound" build/host/juke.log'
run "JUICE WORKS: HOME, the lesson played through (a glass, pouring to the ticket's line, serving, moving a glass)" play help 4 4
run "HOME in a machine: PLAY skips a step (the language stays); left alone, a step is shown again; a knob during the replay goes straight to the turn" play helpknob 4 4
run "JUICE WORKS: ORDER UP! at the start, the order sliding in; a hint after 5 s for the keys, then the knob, then serving" play juicehelp 4 4
run "REC in a game: the box, the game held under it; PLAY on again; REC twice: back to the Arcave" play recask 4 4
run "CRYSTAL ROAD: HOME, the lesson on its own song, on the beat (a low crystal, missed then caught; a high then a low; the miss only shown; KNOB 1 and ALGO)" play helprun 4 3
run "NIGHT BLOOM: HOME, the lesson played through (KNOB 1's petal onto its spore; each on its colour only shown, a key goes on; SELECT's ring, ALGORITHM's ring)" play helpbloom 4 5
run "a new song at the mended jukebox: a long slide, effects, their page, kept (and saved)" sh -c 'tests/run_arcave.sh newsong 4 2 > build/host/newsong.log 2>&1 && grep -q "settings 0 saved" build/host/newsong.log'
run "a song with a part added: OCT+ (the keys an octave up), the two bars filling the strip, RECORDED!; EDIT plays it on while a second part goes over it, PART ADDED!; kept (and saved)" sh -c 'tests/run_arcave.sh newsongdub 4 2 > build/host/newsongdub.log 2>&1 && grep -q "settings 0 saved" build/host/newsongdub.log'
run "the rings, stuck: a minute (the note, HOME breathing), the hint page and back (the note gone), two minutes (HOME held three seconds: the rings glide into line, the light)" play hint 2 1
run "the rings lock as they come into line (the foot shows which), a locked knob does nothing, the light" play lock 2 1
run "the four rings, the dish, a song kept, the power back (and saved)" sh -c 'tests/run_arcave.sh mend 2 1 > build/host/mend.log 2>&1 && grep -q "settings 0 saved" build/host/mend.log'
run "the light back: it swells into the dish, the two cards (PLAY breathing: it skips), then the hand brushing the keys" sh -c 'tests/run_arcave.sh welcome 2 1 > build/host/welcome.log 2>&1 && grep -q "  9800 ms  lights: breathing 0000, PLAY 2" build/host/welcome.log && grep -q " 12900 ms  lights: breathing 0000, PLAY 0" build/host/welcome.log'
run "the welcome skipped by a key: the dish at once" sh -c 'tests/run_arcave.sh welcomeskip 2 1 > build/host/welcomeskip.log 2>&1 && grep -q "  6800 ms  lights: breathing 0000, PLAY 2" build/host/welcomeskip.log && grep -q "  7500 ms  lights: breathing 0000, PLAY 0" build/host/welcomeskip.log'
run "the settings: skip to the Mystic Arcave, OCT+ confirms (and saved)" sh -c 'tests/run_arcave.sh skip > build/host/skip.log 2>&1 && grep -q "settings 0 saved" build/host/skip.log'
run "the lit cave, a tune changed" play lit 4
run "the mended jukebox: its name only in front of it, the offer of a new song only after Rock has left it once" env AT=522,380 sh -c 'tests/run_arcave.sh jukeback 4 9 > build/host/jukeback.log 2>&1 && grep -q "^sound" build/host/jukeback.log'
run "the machines up close, lit: a crystal, a juice press, a flower" env AT=740,330 sh -c 'tests/run_arcave.sh cabinets 4 9 > build/host/cabinets.log 2>&1 && grep -q "^sound" build/host/cabinets.log'
run "the ring secret: only a big hop at full roll off the high right ledge reaches it" env AT=850,167 sh -c 'tests/run_arcave.sh ringjump 4 9 > build/host/ringjump.log 2>&1 && grep -q "cave secret 2 found" build/host/ringjump.log'
run "the keyboard in the cave: every key its note, lowest key lowest, in each tune's own key; with LINK on, the shared key" env AT=466,274 sh -c 'tests/run_arcave.sh keys 4 9 > build/host/keys.log 2>&1 && grep -q "key 0 plays 48 (tune 1)" build/host/keys.log && grep -q "key 13 plays 62 (tune 2)" build/host/keys.log && grep -q "key 0 plays 50 (tune 3)" build/host/keys.log && grep -q "key 13 plays 69 (tune 4)" build/host/keys.log && grep -q "key 26 plays 79 (tune 5)" build/host/keys.log && grep -q "1[0-9]* ms  key 0 plays 45 (tune 3)" build/host/keys.log'
run "the battery: its level in the settings' corner; low, flashing in the corner on any screen" env AT=466,274 sh -c 'tests/run_arcave.sh batt 4 9 > build/host/batt.log 2>&1 && grep -q "^sound" build/host/batt.log'
run "a booster, a secret high up; GLO held does nothing but open the settings as it is let go; on their last line PLAY held three seconds: the save wiped (and saved)" sh -c 'tests/run_arcave.sh boost 4 > build/host/boost.log 2>&1 && grep -q "the whole save wiped" build/host/boost.log && ! grep -q "1[0-7][0-9][0-9][0-9] ms  the whole save wiped" build/host/boost.log'
run "the room up on the left, its door, outside: over the start line" play door 4 7
run "the race back: cheering rock friends where the signs stood" play racecrowd 4 6
run "the race back, start to finish, downhill all the way (and the time saved)" sh -c 'tests/run_arcave.sh race 4 6 > build/host/race.log 2>&1 && grep -q "race back: over the finish" build/host/race.log && grep -q "settings 0 saved" build/host/race.log'
run "the race back, its start: out of the Arcave door at the top, the start line, the first drop" play racestart 4 6
run "the race back, its end: into the opening area, over the finish; the congratulations, the opening course back under them; then the short way down" sh -c 'tests/run_arcave.sh racefinish 4 6 > build/host/racefinish.log 2>&1 && grep -q "race back: the opening course back (Rock at x" build/host/racefinish.log'
run "CRYSTAL ROAD, every note caught: the start card, SPORE DRIFT in PEBBLE to its end (ROCK and CRYSTAL open), KNOB 1 to CRYSTAL, HOME, EDIT: every song (and saved)" env CATCH=1 sh -c 'tests/run_arcave.sh road 4 3 > build/host/road.log 2>&1 && grep -q "CRYSTAL ROAD tune 1 mode 2: 23 notes" build/host/road.log && grep -q "settings 0 saved (3404 B)" build/host/road.log'
run "CRYSTAL ROAD: all six songs, each its own road, SELECT turning the song" env CATCH=1 sh -c 'tests/run_arcave.sh roadsongs 4 3 > build/host/roadsongs.log 2>&1 && grep -q "CRYSTAL ROAD tune 0 mode 0" build/host/roadsongs.log'
run "CRYSTAL ROAD's start card plays the song as a perfect player would, its keys lighting as each note plays" sh -c 'tests/run_arcave.sh roaddemo 4 3 > build/host/roaddemo.log 2>&1 && grep -q "demo: keys lit 00FE000 (tune 1, PEBBLE)" build/host/roaddemo.log'
run "CRYSTAL ROAD, nobody playing: PEBBLE still reaches its end, a key on the result card replays it to practise, then ROCK: the hearts go, GAME OVER" sh -c 'tests/run_arcave.sh road2 4 3 > build/host/road2.log 2>&1 && grep -q "CRYSTAL ROAD tune 1 mode 1" build/host/road2.log && grep -q "PEBBLE) practice" build/host/road2.log'
run "JUICE WORKS: a drink poured and served, a glass moved, a spill" env CATCH=1 sh -c 'tests/run_arcave.sh table 4 4 > build/host/table.log 2>&1 && grep -q "^sound" build/host/table.log'
run "FX a dozen times; child ear protection (and saved)" sh -c 'tests/run_arcave.sh fx 4 > build/host/fx.log 2>&1 && grep -q "settings 0 saved" build/host/fx.log'
run "the profile: the settings' first line, NAME YOUR ROCK (keys type, PRESETS rolls a letter, OCT- rubs out, FX throws the dice), HELLO, the card, the upgrades and back (and saved)" env AT=466,274 sh -c 'tests/run_arcave.sh name 4 9 > build/host/name.log 2>&1 && grep -q "Rock is named" build/host/name.log && grep -q "settings 0 saved" build/host/name.log'
run "EDIT: the upgrades with 600 tickets: a stone, a hat, glasses and a trail bought and worn, a light, a spark, a voice and a jump bought and given to key colours by a key, then too few tickets" env AT=466,274 TICKETS=600 sh -c 'tests/run_arcave.sh shop 4 9 > build/host/shop.log 2>&1 && grep -q "bought MOSSY for 15 tickets, 585 left" build/host/shop.log && grep -q "bought FLIP for 30 tickets, 160 left" build/host/shop.log && ! grep -q "bought STAR JUMP" build/host/shop.log'
run "the tickets: CRYSTAL ROAD's PEBBLE song caught to its end pays 18; back in the Arcave the Hat calls and tells of them" env CATCH=1 sh -c 'tests/run_arcave.sh tickets 4 3 > build/host/tickets.log 2>&1 && grep -q "tickets: 18 paid out, 18 in the pocket" build/host/tickets.log'
run "the gift shop in the room up on the left: the stall and its keeper, Rock settles in front of it, PLAY: the upgrades, EDIT closes; a firm roll on to the door outside" env AT=-64,181 TICKETS=100 sh -c 'tests/run_arcave.sh giftshop 4 9 > build/host/giftshop.log 2>&1 && grep -q "^sound" build/host/giftshop.log'
run "two machines played and no name: the Hat calls from the left, Rock comes, it speaks" env AT=560,380 DONE=3 sh -c 'tests/run_arcave.sh hatcall 4 9 > build/host/hatcall.log 2>&1 && grep -q "the Hat tells: 1" build/host/hatcall.log'
run "the settings with a radio (a pretend one): BLUETOOTH on from the start; off, then on again: starting, waiting, connected" env BT=1 sh -c 'tests/run_arcave.sh btmenu 4 > build/host/btmenu.log 2>&1 && grep -q "settings 0 saved" build/host/btmenu.log'
run "NIGHT BLOOM" play bloom 4 5
run "NIGHT BLOOM, every spore caught: SELECT, ALGORITHM, then KNOB 2 at fifty-eight, each with its arrow" env CATCH=1 sh -c 'tests/run_arcave.sh bloom4 4 5 > build/host/bloom4.log 2>&1 && grep -q "^sound" build/host/bloom4.log'
run "NIGHT BLOOM, every spore caught: as each new ring joins, its first spore comes in alone, ringed" env CATCH=1 sh -c 'tests/run_arcave.sh bloomlead 4 5 > build/host/bloomlead.log 2>&1 && grep -q "^sound" build/host/bloomlead.log'
run "a machine's first visit: NIGHT BLOOM's start card in colour; HOME in a box, no HOME line under it; a knob sets it aside; HOME read: the line back (and saved)" sh -c 'tests/run_arcave.sh homebig 4 5 > build/host/homebig.log 2>&1 && grep -q "settings 0 saved" build/host/homebig.log'
run "a machine's first visit, CRYSTAL ROAD: the HOME box over the card; KNOB 1 sets it aside for three seconds; PLAY: played once" sh -c 'tests/run_arcave.sh homebigtouch 4 3 > build/host/homebigtouch.log 2>&1 && grep -q "^sound" build/host/homebigtouch.log'
run "the emulator's BIG SCREEN: the text one size smaller than the setting" env BIG=1 sh -c 'tests/run_arcave.sh bigtext 4 4 > build/host/bigtext.log 2>&1 && grep -q "^sound" build/host/bigtext.log'
run "EDIT: SUNGLASSES on the face shelf, tried on, bought, worn in the cave" env AT=466,274 TICKETS=600 sh -c 'tests/run_arcave.sh sunglasses 4 9 > build/host/sunglasses.log 2>&1 && grep -q "bought SUNGLASSES for 180 tickets, 420 left" build/host/sunglasses.log'
run "EDIT: the bushy MOUSTACHE (no mouth) on the face shelf, bought, worn in the cave" env AT=466,274 TICKETS=600 sh -c 'tests/run_arcave.sh moustache 4 9 > build/host/moustache.log 2>&1 && grep -q "bought MOUSTACHE for 60 tickets, 540 left" build/host/moustache.log'
run "the small text size" env TSIZE=0 sh -c 'tests/run_arcave.sh story 1 > build/host/story0.log 2>&1 && grep -q "^sound" build/host/story0.log'
run "the large text size" env TSIZE=2 sh -c 'tests/run_arcave.sh story 1 > build/host/story2.log 2>&1 && grep -q "^sound" build/host/story2.log'
run "the well in the cave floor: an old well with a bucket; PLAY: Rock in the bucket, a knob lowers him, the rope snaps, down; REC comes back up" env AT=246,380 sh -c 'tests/run_arcave.sh well 4 9 > build/host/well.log 2>&1 && grep -q "MIDI out BF 110" build/host/well.log && grep -q "MIDI out BF 117 9" build/host/well.log'
run "UNDERSONG with a friend who never misses: the story's four chapters, the finale, the four games' scores, ROCK-OFF (and saved)" env DUO=0 CATCH=1 sh -c 'tests/run_arcave.sh duo 4 10 > build/host/duo.log 2>&1 && grep -q "UNDERSONG NOTE RALLY: 5900 of 3600, 3 stars, chapters 4" build/host/duo.log && grep -q "UNDERSONG ROCK-OFF: 11400 of 11400" build/host/duo.log && grep -q "settings 0 saved (3404 B)" build/host/duo.log'
run "UNDERSONG for three, beside two friends who never miss: the five games for three, each with its own score" env NP=3 DUO=0 CATCH=1 sh -c 'tests/run_arcave.sh trio 4 10 > build/host/trio.log 2>&1 && grep -q "UNDERSONG FOR THREE ECHO STEPS: 10500 of 10500, 3 stars, chapters 3" build/host/trio.log && grep -q "UNDERSONG FOR THREE TWIN ROAD: 14000 of 14000" build/host/trio.log && grep -q "UNDERSONG FOR THREE POTION CHOIR: 1800 of 1800" build/host/trio.log && grep -q "UNDERSONG FOR THREE ROCK-OFF: 11400 of 11400" build/host/trio.log'
run "UNDERSONG, nobody playing beside a friend who never misses: POTION CHOIR is not cleared, the story stays at its first chapter" env DUO=0 sh -c 'tests/run_arcave.sh duoidle 4 10 > build/host/duoidle.log 2>&1 && grep -q "UNDERSONG POTION CHOIR: .* 0 stars, chapters 0" build/host/duoidle.log'
run "the music room: SCL opens THE GEODE, its lesson step by step, then playing, the plectrum, EDIT, scatter" play room 4 11
run "the tunnel off the high right ledge: down it, the door opens, PLAY: into the music room, PLAY at its door: back in the tunnel" env AT=840,160 sh -c 'tests/run_arcave.sh tunnel 4 9 > build/host/tunnel.log 2>&1 && grep -q "^sound" build/host/tunnel.log'
run "the tunnel rolled into slowly: its floor holds Rock (it threw him to its roof), on down to the music room's door" env AT=840,160 sh -c 'tests/run_arcave.sh tunnelslow 4 9 > build/host/tunnelslow.log 2>&1 && grep -q "^sound" build/host/tunnelslow.log'
run "TELEPORT TO MUSIC ROOM in the settings, the story told: a beam out of the cave, a flash, Rock in the music room" env AT=466,274 sh -c 'tests/run_arcave.sh teleport 4 9 > build/host/teleport.log 2>&1 && grep -q "teleported to the music room" build/host/teleport.log'
run "about the music room: the floor, the booster, a slide, a cap, a bubble up to the chimes" play hall 4 11
run "THE POOL, the mixer: levels, a mute, the current, its menu" play pool 4 11
run "ROOTS: its lesson, the wind, the beetle, EDIT" play roots 4 11
run "the music room: GLO held is the quick mix (a mute, a solo, a stop, a level), gone when let go; a tap is the settings, MUSIC ROOM their first line: Rock's sounds, the metronome, the count-in (and saved); REC then waits for the bar" sh -c 'tests/run_arcave.sh quickmix 4 11 > build/host/quickmix.log 2>&1 && grep -q "mix key 0: ROOTS mute 1 solo 0 run 1" build/host/quickmix.log && grep -q "mix key 1: ROOTS mute 1 solo 1" build/host/quickmix.log && grep -q "mix key 6: THE GEODE mute 0 solo 0 run 0" build/host/quickmix.log && grep -q "room setting ROCK.S SOUNDS -> SOFT" build/host/quickmix.log && grep -q "room setting COUNT-IN -> ON" build/host/quickmix.log && grep -q "settings 0 saved" build/host/quickmix.log'
run "the music room: GLO held and FX, ENV or EDIT goes straight to ROOTS, THE POOL, CRYSTAL SEAM, from the floor or another one; letting go of GLO opens no settings" sh -c 'tests/run_arcave.sh glojump 4 11 > build/host/glojump.log 2>&1 && grep -q "GLO + FX: station 1$" build/host/glojump.log && grep -q "GLO + ENV: station 3$" build/host/glojump.log && grep -q "GLO + EDIT: station 5$" build/host/glojump.log'
run "the music room: HOME held in an instrument is HOW IT WORKS, its lessons by topic; one of its own, one every instrument has (LFO), back to the list each time; then the pool's" sh -c 'tests/run_arcave.sh roomtopics 4 11 > build/host/roomtopics.log 2>&1 && grep -q "HOW IT WORKS: THE GEODE, 15 topics" build/host/roomtopics.log && grep -q "topic: SHELL AND STONE" build/host/roomtopics.log && grep -q "topic: LFO: SWINGS" build/host/roomtopics.log && grep -q "HOW IT WORKS: THE POOL, 9 topics" build/host/roomtopics.log && grep -q "topic: MUTE, SOLO, STOP" build/host/roomtopics.log'
run "MUSHROOM RACK: its lesson, the line, the reset, EDIT" play rack 4 11
run "CRYSTAL SEAM: its lesson, breaking and shards, the drip, EDIT" play seam 4 11
run "UNDERSONG, the story told: TWIN ROAD's card turned to another song, and that one is played and scored" env DUO=4 CATCH=1 sh -c 'tests/run_arcave.sh duosong 4 10 > build/host/duosong.log 2>&1 && grep -q "UNDERSONG TWIN ROAD on MYCELIUM NIGHTS: 11600 of 11600, 3 stars" build/host/duosong.log'
run "POTION CHOIR by hand: the friend pours, a knob and a key pour yours (the wrong rock), one round runs out of time" env DUO=0 sh -c 'tests/run_arcave.sh duopot 4 10 > build/host/duopot.log 2>&1 && grep -q "UNDERSONG POTION CHOIR: 600 of 1200, 0 stars, chapters 0" build/host/duopot.log && grep -q "the CPU friend says: THE ONE THAT NEEDS IT IS POINTED, BLUE, WITH TWO EYES, AN O FOR A MOUTH AND TWO CRYSTALS ON ITS HEAD." build/host/duopot.log'
run "NOTE RALLY by hand: a key serves, the note falls where Rock is not, it is served again" env DUO=3 sh -c 'tests/run_arcave.sh duorally 4 10 > build/host/duorally.log 2>&1 && grep -q "UNDERSONG NOTE RALLY: 400 of 3600, 0 stars, chapters 3" build/host/duorally.log'
run "the settings: START UNDERSONG OVER asks which; GLO: neither; OCT-: UNDERSONG's chapters back to none, its scores kept, the banner (and saved)" sh -c 'tests/run_arcave.sh duoreset 4 9 > build/host/duoreset.log 2>&1 && grep -q "UNDERSONG started over: chapters 0, scores kept" build/host/duoreset.log && grep -c "UNDERSONG started over" build/host/duoreset.log | grep -q "^1$" && grep -q "settings 0 saved" build/host/duoreset.log'
run "the settings: START UNDERSONG OVER, OCT+: its chapters and its best scores both (and saved)" sh -c 'tests/run_arcave.sh duowipe 4 9 > build/host/duowipe.log 2>&1 && grep -q "UNDERSONG started over: chapters 0, scores cleared" build/host/duowipe.log && grep -q "settings 0 saved" build/host/duowipe.log'
run "POTION CHOIR's opening runs to its end by itself (the well, the silent choir, the drop, Pink's gleam, Teal pours), then its lesson: two steps shown, a knob and a key at YOUR TURN, two more shown, ALL DONE; then ready and the game" env DUO=0 sh -c 'tests/run_arcave.sh duolesson 4 10 > build/host/duolesson.log 2>&1 && grep -q "lesson: step 3 of 6 done (at your turn)" build/host/duolesson.log && grep -q "lesson: step 4 of 6 done (at your turn)" build/host/duolesson.log && grep -q "lesson: all done" build/host/duolesson.log && grep -q "MIDI out BF 117 6" build/host/duolesson.log'
run "ECHO STEPS, the place: the story's opening runs to its end by itself, then a cave of chasms, each path made by whoever leads and followed by the other, to the Echo's family" env DUO=2 CATCH=1 sh -c 'tests/run_arcave.sh duoecho 4 10 > build/host/duoecho.log 2>&1 && grep -q "UNDERSONG ECHO STEPS: 3500 of 3500, 3 stars, chapters 3" build/host/duoecho.log'
run "ECHO STEPS by hand: PLAY skips the opening; a path of one note, so the Echo adds a stone; the friend's own path next" env DUO=2 sh -c 'tests/run_arcave.sh duopath 4 10 > build/host/duopath.log 2>&1 && grep -q "a stone in round 0, half beat 2, colour 1$" build/host/duopath.log && grep -q "a stone in round 0, half beat 0, colour 1 (the Echo.s)" build/host/duopath.log && grep -q "a stone in round 1, half beat 0" build/host/duopath.log'
run "NOTE RALLY, the place: the story's opening (the door, the giant asleep, the note), PLAY skips its end; the rally in the giant's hall" env DUO=3 CATCH=1 sh -c 'tests/run_arcave.sh duorallyplace 4 10 > build/host/duorallyplace.log 2>&1 && grep -q "^sound" build/host/duorallyplace.log'
run "ONE VOICE: the list's last line, its opening to the end, sixteen walls with both halves played by themselves, the swap, a best (and saved)" env DUO=0 CATCH=1 sh -c 'tests/run_arcave.sh duovoice 4 10 > build/host/duovoice.log 2>&1 && grep -q "UNDERSONG ONE VOICE: 4800 of 4800, 3 stars, chapters 0" build/host/duovoice.log && grep -c "ONE VOICE: wall .* rings" build/host/duovoice.log | grep -q "^16$" && grep -q "settings 0 saved" build/host/duovoice.log'
run "ONE VOICE by hand: a white key held rings the first wall; the knob never turned, the second breaks on its shape" env DUO=0 sh -c 'tests/run_arcave.sh duovoicehand 4 10 > build/host/duovoicehand.log 2>&1 && grep -q "ONE VOICE: wall 1 (height 1, shape 0) rings" build/host/duovoicehand.log && grep -q "ONE VOICE: wall 2 .* breaks: one half was wrong" build/host/duovoicehand.log'
if [ -f build/emu-catch/fm-arcave.wasm ]; then run "UNDERSONG between browser builds wired to each other: seats, one clock, the story, ROCK-OFF, REC, a friend leaving; then three: all five games for three, one going dark" node tests/duo_test.mjs; fi
if [ -f build/emu-catch/fm-arcave.wasm ]; then run "UNDERSONG online: three browser builds through the lobby server (server/node.mjs) and the Online page's code, 80 ms each way: a lobby made, joined, refused; two games for two, a broken connection, ECHO STEPS for three, one leaving" node tests/online_test.mjs; fi
if [ -f build/emu/fm-arcave.wasm ]; then run "the music room with friends: four browser builds through the Link page's relay code; one room sent to each who comes in, one player an instrument, knobs, layouts, the pool, the quick mix, one loop recorded by all, the host going dark, one turning TOGETHER off" node tests/room_test.mjs; fi
if [ -f build/emu/fm-arcave.wasm ]; then run "the music room with friends, 150 ms each way (as online)" node tests/room_test.mjs 150; fi
if [ -f build/emu/fm-arcave.wasm ]; then run "PLAY WITH MY FM-1: a browser build as the FM-1, the page's remote.js, a made-up MIDI port: the save over and back, buttons, keys, knobs, lights, goodbye, silence, a save of another size, a damaged one" node tests/remote_test.mjs; fi
if [ -f build/emu/fm-arcave.wasm ]; then run "PLAY WITH MY FM-1 (BLUETOOTH): the same over a made-up Bluetooth link, 15 ms a connection event, 20-octet packets: both saves whole, nothing dropped, no hello missed" node tests/remote_ble_test.mjs; fi
if [ -f build/emu/fm-arcave.wasm ]; then run "PLAY WITH MY FM-1 (BLUETOOTH) as a Mac: writes taken at once, six packets an event, the FM-1's ring of 64 coming in now and then not read for 40 ms: the page's save paced by what the FM-1 says it has read" node tests/remote_ble_test.mjs mac; fi
run "GLOW CAPS, a machine loaded into the first ledge's slot: its start card over its own picture, HOME's page of its own words, a game, the card after it with its best and the tickets, REC back to the Arcave" env MOD=1 sh -c 'tests/run_arcave.sh glowcaps 4 3 > build/host/glowcaps.log 2>&1 && grep -q "tickets: [0-9]* paid out" build/host/glowcaps.log && grep -q "^sound" build/host/glowcaps.log'
run "the cave with a loaded machine on its second ledge: its cabinet, its name over it" env MOD=2 AT=466,274 sh -c 'tests/run_arcave.sh cabinets 4 9 > build/host/cabinets-mod.log 2>&1 && grep -q "^sound" build/host/cabinets-mod.log'
run "THE SPRING, an instrument loaded into THE GEODE's place of the music room: its lesson of six steps, its knobs, lily pads, the frog, keys of both rows, EDIT, its topics under HOME held, the room with its basin (and saved)" env INS=2 sh -c 'tests/run_arcave.sh spring 4 11 > build/host/spring.log 2>&1 && grep -q "HOW IT WORKS: THE SPRING, 15 topics" build/host/spring.log && grep -q "topic: DEPTH" build/host/spring.log && grep -q "settings 0 saved (3404 B)" build/host/spring.log'
run "the music room as ever with an instrument loaded into another place: THE GEODE's lesson and playing beside THE SPRING in ROOTS' place" env INS=1 sh -c 'tests/run_arcave.sh room 4 11 > build/host/room-ins.log 2>&1 && grep -q "^sound" build/host/room-ins.log'
if [ -f build/emu/fm-arcave.wasm ]; then run "the mystic machines' slots: machine files read, moved and sealed; an FM-1's ledges read; GLOW CAPS loaded in pieces and played; damaged and foreign machines refused; the ledges chosen, kept over a restart; the music room's places the same way (THE SPRING loaded, played, swapped with THE GEODE, each as it was left); the browser game's own bank" node tests/machines_test.mjs; fi
if [ -f build/emu/fm-arcave.wasm ]; then run "the save, backed up: what a save holds, an older one brought up to date, a backup as a file, the list in the browser, an FM-1's save read and put back, the FM-1's own spare copy" node tests/save_test.mjs; fi
run "Bluetooth on the Link pages: the packets (and against the FM-1's codec when it is in the tree), two made-up FM-1s by Bluetooth on the LOCAL and ONLINE pages' own scripts" node tests/ble_web_test.mjs
if [ -f build/emu/fm-arcave.wasm ]; then run "the browser build in Node" node tests/emu_test.mjs; else echo "-- no build/emu: web/emu/build.sh first for the browser test"; fi
run "Bluetooth: the BLE-MIDI packets, the rings, and the platform's rules (the record, the one restart, the boot guard)" sh tests/run_bt_tests.sh
if [ -f build/fm-arcave.fwsc ]; then
    CC="${CC:-cc} -O1 -Wall -Wno-unused-function"
    export AC79_SDK="${AC79_SDK:-$HOME/fw-AC79_AIoT_SDK}"
    $CC -o "$OUT/ota_test" tests/ota_test.c
    run "M-UPGRADE entry: the running firmware takes the package" "$OUT/ota_test" build/fm-arcave.fwsc
    head -c 60000 build/fm-arcave.bin > "$OUT/old_app.bin"
    python3 tools/fm1pkg_make.py "$OUT/old_app.bin" build/loader/ota.bin "$OUT/old.fwsc" >/dev/null
    $CC -o "$OUT/ldr_test" tests/ldr_test.c
    run "update loader: another app -> this build" "$OUT/ldr_test" "$OUT/old.fwsc" build/fm-arcave.fwsc
else echo "-- no build/fm-arcave.fwsc: ./build.sh first for the update-path tests"; fi
[ "$fail" = 0 ] && echo "all passed" || { echo "some tests failed"; exit 1; }
